mapper.update:
UPDATE tb_material_arrival_dt
SET line_no = #{lineNo},
    updated_by = #{updatedBy},
    updated_at = now()
WHERE material_arrival_detail_id = #{materialArrivalDetailId, jdbcType=BIGINT}
  AND material_arrival_id = #{materialArrivalId, jdbcType=BIGINT}
  AND tenant_id = #{tenantId, jdbcType=BIGINT}

